-- ============================================================================
-- ATS SAAS · Fase 3 · Reconciliación completa de ventas contra el Excel
--
-- La carga 0016 solo trajo las ventas posteriores al 2026-07-09, asumiendo
-- que la base ya tenía todas las anteriores. No era así: faltaban servicios
-- en el tramo que se dio por cubierto.
--
-- Esta migración recorre las 325 ventas con fecha del Excel y agrega
-- únicamente las que faltan. Es re-ejecutable.
--
-- Corrige dos errores de tipeo en el año, deducidos de la fecha de
-- facturación: 2 filas (2002-10-07 facturada el 2026-10-13, y
-- 2016-10-15 facturada el 2026-10-19). La fecha original queda escrita en el
-- comentario para que la corrección sea auditable.
--
-- Queda fuera 1 fila sin fecha de servicio: Andes Solar, guía 10315, neto
-- 280.000. Por sus vecinas es de la semana del 22 al 27 de julio de 2026,
-- pero el día exacto no se puede deducir y fecha_servicio es obligatoria.
--
-- LA DEDUPLICACIÓN CUENTA OCURRENCIAS, no pregunta si existe. Hay dos pares
-- de servicios distintos que comparten fecha, cliente y montos:
--   2026-02-26 Subcargo    (IDs 166 y 167, ambos 310.000)
--   2026-04-24 Andes Solar (ID 208 dos veces, 200.000)
-- Un "not exists" habría descartado uno de cada par. Comparando cuántas veces
-- aparece cada combinación en el Excel contra cuántas hay en la base, los dos
-- entran y nada se duplica.
-- ============================================================================

begin;

create temp table _v_todas (
  fecha_servicio date, cliente text, proyecto_obra text, origen text, destino text,
  servicio_tipo text, comentario text, valor_pluma_hora numeric(14,2), cantidad_horas numeric(10,2),
  valor_flete numeric(14,2), extras numeric(14,2), n_guia text, n_oc text, descripcion_carga text,
  n_cotizacion text, n_factura text, fecha_facturacion date, fecha_estimada_pago date,
  fecha_pago date, operador text, variable_operador numeric(14,2), salida_caja numeric(14,2),
  viaticos_extras numeric(14,2), comision_venta numeric(14,2), pago_terceros numeric(14,2),
  pago_iva_terceros numeric(14,2), n_factura_tercero text, n_reporte text, km_inicio numeric(10,1),
  km_fin numeric(10,1), km_servicio numeric(10,1), costos_petroleo_tct numeric(14,2),
  h_operacion numeric(10,2), tag_peajes numeric(14,2)
) on commit drop;

