-- Clientes y operadores que pudieran faltar.
insert into public.clientes (nombre)
select distinct cliente from _v_todas where cliente is not null
on conflict (nombre) do nothing;

insert into public.operadores (nombre)
select distinct operador from _v_todas where operador is not null
on conflict (nombre) do nothing;

-- Numera cada fila dentro de su combinación repetida.
with excel as (
  select i.*, c.id as cliente_id, o.id as operador_id,
    row_number() over (
      partition by i.fecha_servicio, i.cliente, coalesce(i.n_guia,''),
                   coalesce(i.valor_pluma_hora,0), coalesce(i.cantidad_horas,0),
                   coalesce(i.valor_flete,0), coalesce(i.extras,0)
      order by i.n_factura nulls last, i.descripcion_carga nulls last
    ) as ocurrencia
  from _v_todas i
  join public.clientes c on c.nombre = i.cliente
  left join public.operadores o on o.nombre = i.operador
),
ya_en_base as (
  select v.fecha_servicio, v.cliente_id, coalesce(v.n_guia,'') as n_guia,
         coalesce(v.valor_pluma_hora,0) as vph, coalesce(v.cantidad_horas,0) as ch,
         coalesce(v.valor_flete,0) as vf, coalesce(v.extras,0) as ex,
         count(*) as cuantas
  from public.ventas_servicios v
  group by 1,2,3,4,5,6,7
)
insert into public.ventas_servicios (
  fecha_servicio, cliente_id, proyecto_obra, origen, destino, servicio_tipo, comentario,
  valor_pluma_hora, cantidad_horas, valor_flete, extras, n_guia, n_oc, descripcion_carga,
  n_cotizacion, n_factura, fecha_facturacion, fecha_estimada_pago, fecha_pago, operador_id,
  variable_operador, salida_caja, viaticos_extras, comision_venta, pago_terceros,
  pago_iva_terceros, n_factura_tercero, n_reporte, km_inicio, km_fin, km_servicio,
  costos_petroleo_tct, h_operacion, tag_peajes)
select e.fecha_servicio, e.cliente_id, e.proyecto_obra, e.origen, e.destino, e.servicio_tipo,
  e.comentario, e.valor_pluma_hora, e.cantidad_horas, e.valor_flete, e.extras, e.n_guia,
  e.n_oc, e.descripcion_carga, e.n_cotizacion, e.n_factura, e.fecha_facturacion,
  e.fecha_estimada_pago, e.fecha_pago, e.operador_id, e.variable_operador, e.salida_caja,
  e.viaticos_extras, e.comision_venta, e.pago_terceros, e.pago_iva_terceros,
  e.n_factura_tercero, e.n_reporte, e.km_inicio, e.km_fin, e.km_servicio,
  e.costos_petroleo_tct, e.h_operacion, e.tag_peajes
from excel e
left join ya_en_base b
  on b.fecha_servicio = e.fecha_servicio
 and b.cliente_id = e.cliente_id
 and b.n_guia = coalesce(e.n_guia,'')
 and b.vph = coalesce(e.valor_pluma_hora,0)
 and b.ch = coalesce(e.cantidad_horas,0)
 and b.vf = coalesce(e.valor_flete,0)
 and b.ex = coalesce(e.extras,0)
where e.ocurrencia > coalesce(b.cuantas, 0);

commit;
